import { z } from 'zod';

/** Entity identifiers are UUIDs generated by the database. */
export const IdSchema = z.uuid();
export type Id = z.infer<typeof IdSchema>;

/** Timestamps cross the wire as ISO 8601 strings with an offset. */
export const IsoDateTimeSchema = z.iso.datetime({ offset: true });
export type IsoDateTime = z.infer<typeof IsoDateTimeSchema>;

/** The product is USD only (spec section 3). */
export const CurrencySchema = z.literal('USD');
export type Currency = z.infer<typeof CurrencySchema>;

/** Money is always an integer number of cents (decision 2026-11-07-integer-cents). */
export const CentsSchema = z.number().int().nonnegative();
export type Cents = z.infer<typeof CentsSchema>;
